def maxParentheses(n: int, s: str, v: list[int]) -> int:
    import heapq
    pq = []
    ans = 0
    for char, val in zip(s, v):
        if char == '(':
            heapq.heappush(pq, -val)
        else:
            if pq and (-pq[0] + val > 0):
                top = -heapq.heappop(pq)
                ans += top + val
                heapq.heappush(pq, -(-val))
    return ans
